class InvoiceReport {
	line(invoice: Invoice): string {
		const gross = invoice.getItems().reduce((sum, item) => sum + item.getPrice() * item.getQuantity(), 0);
		const discount = invoice.getCustomer().isPremium() ? gross * 0.1 : 0;
		const tax = (gross - discount) * invoice.getTaxRate();
		return `${invoice.getNumber()}: ${gross - discount + tax}`;
	}
}

